    id: "est-ks2-19-04",
    ...T19,
    kapitel: "4",
    title: "4 Pauschbeträge für Arbeitnehmer, § 9a Nr. 1 EStG",
    thema: "Arbeitnehmer-Pauschbetrag und Pauschbetrag für Versorgungsbezüge",
    rechtsstand: RECHTSSTAND,
    quelle: "ESt Kurzskript II (Engelberth) · Nichtselbständige Arbeit, Kapitel 4",
    verfasser: VERFASSER,
